1	export type Cell = [number, number];
2	
3	const NEIGHBOUR_OFFSETS: Cell[] = [
4	  [-1, -1],
5	  [-1, 0],
6	  [-1, 1],
7	  [0, -1],
8	  [0, 1],
9	  [1, -1],
10	  [1, 0],
11	  [1, 1],
12	];
13	
14	const NEIGHBOURS_NEEDED_TO_SURVIVE = [2, 3];
15	const NEIGHBOURS_NEEDED_TO_BE_BORN = 3;
16	
17	const keyOf = ([x, y]: Cell): string => `${x},${y}`;
18	
19	const distinct = (cells: Cell[]): Cell[] => [
20	  ...new Map(cells.map((cell) => [keyOf(cell), cell])).values(),
21	];
22	
23	export function nextGeneration(liveCells: Cell[]): Cell[] {
24	  const liveKeys = new Set(liveCells.map(keyOf));
25	  const isLive = (cell: Cell): boolean => liveKeys.has(keyOf(cell));
26	
27	  const neighboursOf = ([x, y]: Cell): Cell[] =>
28	    NEIGHBOUR_OFFSETS.map(([dx, dy]) => [x + dx, y + dy]);
29	
30	  const countLiveNeighbours = (cell: Cell): number =>
31	    neighboursOf(cell).filter(isLive).length;
32	
33	  const survives = (cell: Cell): boolean =>
34	    NEIGHBOURS_NEEDED_TO_SURVIVE.includes(countLiveNeighbours(cell));
35	
36	  const isBorn = (cell: Cell): boolean =>
37	    !isLive(cell) && countLiveNeighbours(cell) === NEIGHBOURS_NEEDED_TO_BE_BORN;
38	
39	  const born = distinct(liveCells.flatMap(neighboursOf)).filter(isBorn);
40	
41	  return [...liveCells.filter(survives), ...born];
42	}
